using System.ComponentModel;
using System.Net;
using System.Text;
using System.Text.Json;
using Microsoft.Extensions.AI;
using OpenAI;

// --- Configuration ---
var modelName = Environment.GetEnvironmentVariable("OPENAI_MODEL") ?? "gpt-4o-mini";
var apiKey = Environment.GetEnvironmentVariable("OPENAI_API_KEY")
    ?? throw new InvalidOperationException("Set the OPENAI_API_KEY environment variable.");

// --- Build chat client with automatic function invocation ---
IChatClient client = new OpenAIClient(apiKey)
    .GetChatClient(modelName)
    .AsIChatClient()
    .AsBuilder()
    .UseFunctionInvocation()
    .Build();

// --- Tools ---
var notepad = new Notepad();

var tools = new AITool[]
{
    AIFunctionFactory.Create(WebSearchTool.SearchAsync),
    AIFunctionFactory.Create(WebSearchTool.FetchPageAsync),
    AIFunctionFactory.Create(notepad.AddNote),
    AIFunctionFactory.Create(notepad.GetNotes),
};

// --- Get research topic ---
Console.Write("Enter a research topic: ");
var topic = Console.ReadLine()?.Trim();
if (string.IsNullOrEmpty(topic))
{
    Console.WriteLine("No topic provided. Exiting.");
    return;
}

Console.WriteLine($"\n🔍 Researching: {topic}\n");

// --- Agent loop ---
var messages = new List<ChatMessage>
{
    new(ChatRole.System, """
        You are a research agent. Your job is to thoroughly research the given topic using the
        available tools and produce a well-structured summary.

        Workflow:
        1. Search the web for information about the topic (try 2-3 different search queries).
        2. Fetch the most relevant pages to get details.
        3. Take notes on key findings using the note-taking tool.
        4. After gathering enough information, retrieve all your notes and write a final summary.

        Be thorough but concise. Cite sources where possible.
        """),
    new(ChatRole.User, $"Please research the following topic and provide a summary: {topic}"),
};

var options = new ChatOptions { Tools = [.. tools] };

var response = await client.GetResponseAsync(messages, options);

Console.WriteLine("\n" + new string('═', 60));
Console.WriteLine("📋 RESEARCH SUMMARY");
Console.WriteLine(new string('═', 60));
Console.WriteLine(response.Text);
Console.WriteLine(new string('═', 60));

if (notepad.Count > 0)
{
    Console.WriteLine($"\n📝 {notepad.Count} note(s) were taken during research.");
}

