// Tool implementations
// ============================================================

/// <summary>Web search and page fetching tools.</summary>
static class WebSearchTool
{
    private static readonly HttpClient Http = new()
    {
        DefaultRequestHeaders =
        {
            { "User-Agent", "ResearchAgent/1.0" },
            { "Accept", "text/html" },
        },
        Timeout = TimeSpan.FromSeconds(15),
    };

    [Description("Search the web for a query. Returns a list of result titles and URLs.")]
    public static async Task<string> SearchAsync(
        [Description("The search query string")] string query)
    {
        Console.WriteLine($"  🌐 Searching: \"{query}\"");
        try
        {
            var encoded = WebUtility.UrlEncode(query);
            var url = $"https://html.duckduckgo.com/html/?q={encoded}";
            var html = await Http.GetStringAsync(url);
            return ParseSearchResults(html);
        }
        catch (Exception ex)
        {
            return $"Search failed: {ex.Message}";
        }
    }

    [Description("Fetch the text content of a web page given its URL. Returns the page text (truncated to ~4000 chars).")]
    public static async Task<string> FetchPageAsync(
        [Description("The full URL to fetch")] string url)
    {
        Console.WriteLine($"  📄 Fetching: {url}");
        try
        {
            var html = await Http.GetStringAsync(url);
            var text = StripHtml(html);
            return text.Length > 4000 ? text[..4000] + "\n... [truncated]" : text;
        }
        catch (Exception ex)
        {
            return $"Fetch failed: {ex.Message}";
        }
    }

    private static string ParseSearchResults(string html)
    {
        var sb = new StringBuilder();
        int count = 0;

        // Parse DuckDuckGo HTML results: look for <a class="result__a" href="...">title</a>
        var span = html.AsSpan();
        while (count < 8)
        {
            const string marker = "class=\"result__a\"";
            int idx = span.IndexOf(marker);
            if (idx < 0) break;

            span = span[(idx + marker.Length)..];

            // Extract href
            int hrefStart = span.IndexOf("href=\"");
            if (hrefStart < 0) break;
            span = span[(hrefStart + 6)..];
            int hrefEnd = span.IndexOf("\"");
            if (hrefEnd < 0) break;
            var href = span[..hrefEnd].ToString();
            span = span[hrefEnd..];

            // Extract title text (between > and </a>)
            int gtIdx = span.IndexOf(">");
            if (gtIdx < 0) break;
            span = span[(gtIdx + 1)..];
            int closeIdx = span.IndexOf("</a>");
            if (closeIdx < 0) break;
            var title = StripHtml(span[..closeIdx].ToString()).Trim();
            span = span[closeIdx..];

            if (!string.IsNullOrWhiteSpace(title) && href.StartsWith("http"))
            {
                count++;
                sb.AppendLine($"{count}. {title}");
                sb.AppendLine($"   URL: {href}");
            }
        }

        return count > 0
            ? $"Found {count} results:\n{sb}"
            : "No results found. Try a different query.";
    }

    private static string StripHtml(string html)
    {
        // Remove script/style blocks, then tags, then collapse whitespace
        var text = System.Text.RegularExpressions.Regex.Replace(html, @"<(script|style)[^>]*>[\s\S]*?</\1>", " ");
        text = System.Text.RegularExpressions.Regex.Replace(text, @"<[^>]+>", " ");
        text = WebUtility.HtmlDecode(text);
        text = System.Text.RegularExpressions.Regex.Replace(text, @"\s+", " ");
        return text.Trim();
    }
}

/// <summary>Simple note-taking tool that stores notes in memory.</summary>
class Notepad
{
    private readonly List<(string Topic, string Content)> _notes = [];

    public int Count => _notes.Count;

    [Description("Save a research note. Use this to record key findings as you research.")]
    public string AddNote(
        [Description("Short topic/label for this note")] string topic,
        [Description("The note content with details and source URLs")] string content)
    {
        _notes.Add((topic, content));
        Console.WriteLine($"  📝 Note added: \"{topic}\"");
        return $"Note #{_notes.Count} saved under \"{topic}\".";
    }

    [Description("Retrieve all saved research notes.")]
    public string GetNotes()
    {
        if (_notes.Count == 0)
            return "No notes saved yet.";

        var sb = new StringBuilder();
        for (int i = 0; i < _notes.Count; i++)
        {
            sb.AppendLine($"--- Note #{i + 1}: {_notes[i].Topic} ---");
            sb.AppendLine(_notes[i].Content);
            sb.AppendLine();
        }
        return sb.ToString();
    }
}

